package com.shatteredpixel.shatteredpixeldungeon.apd.mechanics;

import com.shatteredpixel.shatteredpixeldungeon.Dungeon;
import com.shatteredpixel.shatteredpixeldungeon.actors.buffs.*;
import com.shatteredpixel.shatteredpixeldungeon.actors.hero.Hero;
import com.shatteredpixel.shatteredpixeldungeon.actors.hero.Talent;
import com.shatteredpixel.shatteredpixeldungeon.items.Item;

/** Additional reviewed status rules, with no random rolls or effect-handler calls. */
public final class BuffExplanation {
    private BuffExplanation(){}
    private static String n(float x){return ObfuscationExplanation.number(x);}
    public static String details(Buff buff){
        if(buff instanceof com.shatteredpixel.shatteredpixeldungeon.items.BrokenSeal.WarriorShield){
            com.shatteredpixel.shatteredpixeldungeon.items.BrokenSeal.WarriorShield shield=(com.shatteredpixel.shatteredpixeldungeon.items.BrokenSeal.WarriorShield)buff;
            int cooldown=shield.remainingCooldown();
            String text="_Seal shield_\nCurrent shield: "+shield.shielding()+" points. Original shield at last activation: "+shield.activationShield()+" points. ";
            if(buff.target==Dungeon.hero && Dungeon.hero!=null)text+="Next activation: "+shield.maxShield()+" shield points. ";
            text+=cooldown>0?"Recharge remaining: "+cooldown+" turns while regeneration is allowed. ":cooldown<0?"Stored cooldown reduction: "+(-cooldown)+" turns, deducted from the next recharge. ":"Ready to activate. ";
            return text+"Positive non-hunger damage can activate it when health is at or below half, or the incoming hit after existing shields would cross that threshold. Each activation adds its shield capacity and "+shield.cooldownDuration()+" turns of recharge, reduced by any stored credit. Hunger alone does not pause recharging.\n\n_Shield expiry_\nEnemy-free decay progress: "+n(shield.enemyFreeProgress())+" of 5. Normally advances by 1 each turn without visible enemies or an active Gladiator combo; Hold Fast slows or pauses it. Enemies or a combo reset it. At 5, remaining shield disappears and can refund recharge time.\n\n_Details_\nWarrior sealed-armor capacity = 3 + 2 × armor tier + Iron Will rank. Armor upgrades do not increase it. The separate non-Warrior Iron Will benefit equals its rank. Activation threshold = floor(maximum HP / 2). Recharge refund = "+shield.cooldownDuration()+" × (shield left / original shield) / 2; subtract it from remaining recharge, round down, and stop at zero.";
        }

        if(buff instanceof com.shatteredpixel.shatteredpixeldungeon.items.potions.elixirs.ElixirOfMight.HTBoost && buff.target instanceof Hero){
            com.shatteredpixel.shatteredpixeldungeon.items.potions.elixirs.ElixirOfMight.HTBoost boost=(com.shatteredpixel.shatteredpixeldungeon.items.potions.elixirs.ElixirOfMight.HTBoost)buff;
            return "_Temporary maximum health_\nBase maximum-HP bonus: _"+boost.boost()+" HP_, before your run's health modifier. Level-ups remaining: _"+boost.remainingLevelSteps()+" of 5_. Each level-up weakens the bonus until it disappears; ordinary turns do not wear it down. The amount depends on your level, and other maximum-HP bonuses do not increase it.";
        }
        if(buff instanceof com.shatteredpixel.shatteredpixeldungeon.items.potions.elixirs.ElixirOfAquaticRejuvenation.AquaHealing){
            return "_Healing in water_\nStored healing reserve: "+((com.shatteredpixel.shatteredpixeldungeon.items.potions.elixirs.ElixirOfAquaticRejuvenation.AquaHealing)buff).remainingHealingPool()+" HP. While grounded in water, normally heals about 2% of maximum HP per turn, with a minimum of 1 HP before healing modifiers. Pauses on dry ground, while flying or at full health. Your healing rules change the HP restored; the reserve still pays the normal amount, even when healing is disabled.";
        }
        if(buff instanceof Barkskin || buff instanceof ArcaneArmor){
            int interval=buff instanceof Barkskin?((Barkskin)buff).decayInterval():((ArcaneArmor)buff).decayInterval();
            return "_Fading protection_\nEach update reduces maximum protection by 1 damage point. Later losses are "+interval+" turns apart. Protection ends when this maximum reaches zero. Each protected hit blocks a random amount up to the current maximum; other defenses still apply.";
        }
        if(buff instanceof RevealedArea)return "_Temporary local sight_\nReveals a 3 × 3 area around the original impact tile on its original floor and branch. It stays there rather than following a moving target. This does not identify items or discover hidden doors.";
        if(buff instanceof PinCushion){int count=0;for(com.shatteredpixel.shatteredpixeldungeon.items.weapon.missiles.MissileWeapon item:((PinCushion)buff).getStuckItems())count+=item.quantity();return "_Embedded projectiles_\nRecoverable projectile quantity: "+count+". These drop at the carrier's position when this effect ends. Stacked projectiles count individually. Projectiles already destroyed by wear cannot be recovered.";}
        if(buff instanceof GravityChaosTracker){GravityChaosTracker gravity=(GravityChaosTracker)buff;return "_Unpredictable gravity_\nRemaining pulse count: "+gravity.left+". Each pulse pushes movable characters in one random direction, normally 1–3 turns after the previous pulse. Walls and other characters limit how far they move; blocked characters can delay a pulse. "+(gravity.positiveOnly?"This version excludes allied characters.":"Allies can be pushed too.");}
        if(buff instanceof SwarmIntelTracker)return "_Enemy alert range_\nLargest alert range last observed among visible monsters: "+((SwarmIntelTracker)buff).observedAlertRange()+" tiles. This does not scan unseen enemies or mean every monster has that range. The indicator may linger briefly after no alert range is observed.";
        if(buff.target==com.shatteredpixel.shatteredpixeldungeon.Dungeon.hero&&Dungeon.hero!=null){
            if(buff instanceof com.shatteredpixel.shatteredpixeldungeon.actors.hero.spells.HolyWeapon.HolyWepBuff)return SpellExplanation.effects(com.shatteredpixel.shatteredpixeldungeon.actors.hero.spells.HolyWeapon.INSTANCE,Dungeon.hero);
            if(buff instanceof com.shatteredpixel.shatteredpixeldungeon.actors.hero.spells.HolyWard.HolyArmBuff)return SpellExplanation.effects(com.shatteredpixel.shatteredpixeldungeon.actors.hero.spells.HolyWard.INSTANCE,Dungeon.hero);
            if(buff instanceof com.shatteredpixel.shatteredpixeldungeon.actors.hero.spells.AuraOfProtection.AuraBuff)return SpellExplanation.effects(com.shatteredpixel.shatteredpixeldungeon.actors.hero.spells.AuraOfProtection.INSTANCE,Dungeon.hero);
            if(buff instanceof com.shatteredpixel.shatteredpixeldungeon.actors.hero.spells.ShieldOfLight.ShieldOfLightTracker)return SpellExplanation.effects(com.shatteredpixel.shatteredpixeldungeon.actors.hero.spells.ShieldOfLight.INSTANCE,Dungeon.hero);
            if(buff instanceof com.shatteredpixel.shatteredpixeldungeon.actors.hero.spells.DivineSense.DivineSenseTracker)return SpellExplanation.effects(com.shatteredpixel.shatteredpixeldungeon.actors.hero.spells.DivineSense.INSTANCE,Dungeon.hero);
        }
        if(buff instanceof com.shatteredpixel.shatteredpixeldungeon.actors.hero.spells.GuidingLight.Illuminated&&Dungeon.hero!=null)return SpellExplanation.effects(com.shatteredpixel.shatteredpixeldungeon.actors.hero.spells.GuidingLight.INSTANCE,Dungeon.hero);
        if(buff instanceof ScrollEmpower){
            ScrollEmpower empower=(ScrollEmpower)buff;
            return "_Stronger wand casts_\nWand casts left: "+empower.remainingUses()+". Your carried wands cast as if upgraded twice, without gaining charges or permanent upgrades. This boost applies after Degradation; later Desperate Power, Wild Magic and Magic Charge effects can change the final cast.\n\n_Using the bonus_\nEach cast normally spends 1 use, regardless of charge cost. Magic Charge from another wand is spent instead when its level matches the cast's boosted level and exceeds the casting wand's ordinary level. Refreshing keeps the larger number of uses, rather than adding them. Lasts until its uses are spent.";
        }
        if(buff instanceof HoldFast){
            HoldFast hold=(HoldFast)buff;
            if(!(buff.target instanceof Hero))return "Only heroes benefit from Hold Fast.";
            Hero owner=(Hero)buff.target;
            return (owner.pos==hold.pos?"_Holding position_\nBonus currently active at this position.":"_Left the position_\nBonus currently inactive because you moved.")
                +"\n"+TalentExplanation.details(Talent.HOLD_FAST,owner.pointsInTalent(Talent.HOLD_FAST));
        }
        if(buff instanceof MagicalSight)return "_Sight through walls_\nSenses nearby terrain through walls, up to "+MagicalSight.DISTANCE+" tiles away, without shortening ordinary sight. When local sensing ranges overlap, the larger radius is used rather than adding them. Removes Blindness and prevents it while active. Seeing a hidden door or trap's disguised tile does not discover it.";
        if(buff instanceof MindVision){int distance=((MindVision)buff).distance;return "_Mind Vision_\nSenses creatures across this floor and reveals the nearby area around them. Also senses local terrain within "+distance+(distance==1?" tile":" tiles")+", complementing ordinary sight. Overlapping local sensing ranges use the larger radius. Undisturbed stealthy mimics and inanimate objects are not sensed. This does not map the whole floor or let projectiles pass through walls.";}
        if(buff instanceof Shadows){
            Shadows shadows=(Shadows)buff;
            return "_Concealed in foliage_\nKeeps you invisible but limits normal sight to nearby terrain; other senses can help. Enemies can investigate your last known position, and area effects can still hurt you. Attacks and magic can break concealment.\n\n_Refresh and hunger_\nRefresh countdown: "+n(shadows.remainingShadowUpdates())+" updates, normally one update per turn. Foliage resets this to 2 instead of adding time. Ends at zero or when an adjacent creature is not an ally. Hunger advances at two thirds of its usual rate before Salt Cube and run modifiers; this does not protect against starvation damage.";
        }
        if(buff instanceof MonkEnergy){
            MonkEnergy energy=(MonkEnergy)buff;
            if(Dungeon.hero==null)return "Monk energy is a spendable ability resource. A current hero is needed for level-dependent capacity and empowerment details.";
            int cap=energy.energyCap(),rank=Dungeon.hero.pointsInTalent(Talent.MONASTIC_VIGOR);
            StringBuilder costs=new StringBuilder();for(MonkEnergy.MonkAbility ability:MonkEnergy.MonkAbility.abilities){if(costs.length()>0)costs.append(", ");costs.append(ability.name()).append(" ").append(ability.energyCost());}
            return "_Monk energy and empowerment_\nEnergy: _"+n(energy.energy)+"/"+cap+"_. Capacity = max(10, 5 + round down(hero level / 2)); fractions of energy are kept. Ability energy costs: "+costs+". Waiting does not refill energy."
                +"\n\nKills normally give 1 energy; bosses give 5, minibosses 3, and ghouls, ripper demons, Yog larvae and wraiths 0.5 unless they count as bosses or minibosses. Gains pause when the floor disables natural recovery. Unencumbered Spirit adds separate armor and melee-weapon bonuses to the gain: +100% for tier 1 or lower at rank 3, otherwise +75% for tier 2 or lower at rank 2+, otherwise +50% for tier 3 or lower at rank 1+. Empty equipment slots give no bonus. Active Brawler’s Stance excludes the weapon bonus. Gains normally stop at capacity; a kill during an unarmed ability can exceed it until the ability spends energy and applies the cap."
                +"\n\nEmpowerment requires energy / capacity ≥ 1.2 − 0.2 × Monastic Vigor rank. Exact threshold at your rank: "+Float.toString(1.2f-.2f*rank)+"; your current ratio: "+Float.toString(energy.energy/cap)+". Rounded percentages can hide the boundary just above 80% at rank 2. Empowered now: _"+(energy.abilitiesEmpowered(Dungeon.hero)?"yes":"no")+"_."
                +(energy.cooldown>0?" Ability cooldown: "+energy.cooldown+" turns.":"")
                +"\n\n"+MonkAbilityExplanation.details(energy,Dungeon.hero);
        }
        if(buff instanceof Momentum){
            Momentum momentum=(Momentum)buff;
            String rate=buff.target!=null&&Dungeon.hero!=null?"Walking speed from this effect: _"+n(momentum.speedMultiplier())+"× normal_.":"Freerunning normally doubles walking speed.";
            return "_Momentum_\nStored momentum: _"+momentum.storedStacks()+" of 10_. Freerunning turns left: _"+momentum.remainingRunUpdates()+"_. Recovery turns left: _"+momentum.remainingCooldownUpdates()+"_. "+rate+" Attacks are unchanged.\n\n_Starting a run_\nEach momentum point buys 2 turns of freerunning. Recovery starts with the run at 10 + 4 × momentum spent, and counts down during it. Each normal step builds 1 momentum when you are ready to run; stopping quickly loses it.\n\n_Stealth and evasion_\nWith Speedy Stealth learned, each eligible invisible turn grants 2 momentum. At rank 2+, invisibility pauses freerunning's countdown while recovery continues. Rank 3 also doubles walking speed while invisible outside freerunning, without granting freerunning's extra evasion.\nWhile freerunning in armor, normal dodging gains half your level in evasion, rounded down, plus Evasive Armor rank per point of excess strength. Stone uses its own defense rule.";
        }
        if(buff instanceof Invisibility)return "_Invisibility and enemy awareness_\nOrdinary enemies cannot see you, but may investigate your last known position. Attacks and many magical actions break invisibility. Area effects, environmental damage and special senses can still affect you. If another source keeps you invisible, ending one source may not reveal you.";
        if(buff instanceof Invulnerability)return "_Temporary damage protection_\nBlocks ordinary damage while active. It does not prevent every harmful status or special instant-death effect. Hits do not use up its duration or a reserve of protection points.";
        if(buff instanceof com.shatteredpixel.shatteredpixeldungeon.plants.Swiftthistle.TimeBubble)return "_Time Bubble_\nFree action time left: "+n(((com.shatteredpixel.shatteredpixeldungeon.plants.Swiftthistle.TimeBubble)buff).remainingActionTime())+" turns. An action spends its normal turn cost from this amount while the rest of the dungeon waits. The initial amount includes the action that activates it. Attacking or using magic ends the bubble. Plants and traps you stepped on are delayed until it ends.";
        if(buff instanceof com.shatteredpixel.shatteredpixeldungeon.plants.Sungrass.Health){
            com.shatteredpixel.shatteredpixeldungeon.plants.Sungrass.Health healing=(com.shatteredpixel.shatteredpixeldungeon.plants.Sungrass.Health)buff;
            String result="_Herbal healing_\nStored healing: "+healing.remainingPool()+" HP before healing adjustments. Each turn adds (40 + maximum HP) / 150 to healing progress. Once progress exceeds 1 HP, its whole-number part is spent and the fraction is saved. The last heal can slightly exceed the remaining store. More herbal healing adds to the store. Moving ends the effect, though one final heal may occur as it ends.";
            if(buff.target==Dungeon.hero&&Dungeon.hero!=null)result+="\nCurrent progress: "+n(healing.healingProgress())+" HP; next base heal: "+healing.nextUnmodifiedRequest()+" HP, before your run's healing rule and maximum-health limit.";
            return result;
        }
        if(buff instanceof com.shatteredpixel.shatteredpixeldungeon.items.wands.WandOfLivingEarth.RockArmor){
            com.shatteredpixel.shatteredpixeldungeon.items.wands.WandOfLivingEarth.RockArmor armor=(com.shatteredpixel.shatteredpixeldungeon.items.wands.WandOfLivingEarth.RockArmor)buff;
            return "_Rock Armor_\nCurrent reserve: "+armor.remainingReserve()+" damage-blocking points. Each attack uses min(reserve, ceil(incoming damage / 2)) points to block that much damage. Other defenses apply separately. Guardian threshold: "+armor.guardianThreshold()+" reserve points = 8 + 4 × wand power. Maximum reserve: "+(2*armor.guardianThreshold())+". A Living Earth zap can summon the guardian once this threshold is reached, if there is room.";
        }
        if(buff instanceof com.shatteredpixel.shatteredpixeldungeon.plants.Earthroot.Armor){
            com.shatteredpixel.shatteredpixeldungeon.plants.Earthroot.Armor armor=(com.shatteredpixel.shatteredpixeldungeon.plants.Earthroot.Armor)buff;
            return "_Earthroot protection_\nBlocks up to "+armor.perHitLimit()+" damage per attack while you stay on the protected tile. Remaining reserve: "+armor.remainingReserve()+" points. Blocked damage spends reserve; the final hit can still block the full per-hit amount. Moving ends protection.\nPer-hit limit = floor((dungeon depth + 5) / 2). During the ascension challenge, use depth 26.";
        }
        if(buff instanceof com.shatteredpixel.shatteredpixeldungeon.items.wands.WandOfLightning.LightningCharge)return "_Lightning Charge_\nProtects against Lightning wand damage. A charged caster's lightning jumps 1 tile farther along open paths: up to 2 tiles from a dry target, or 3 from a target standing in water. Other sources of electricity can still hurt you. Reapplying keeps the longer time remaining.";
        if(buff instanceof Paralysis){
            String result="_Breaking paralysis_\nTaking damage can break paralysis, even before shield points absorb the hit. More accumulated damage and lower current HP improve the chance; no single hit guarantees escape.\n\n_Escape check_\nRoll from 0 to accumulated damage and separately from 0 to current HP, favoring middle results. Escape succeeds when the damage roll is at least the HP roll. Each roll is the whole-number part of (two random fractions added together) × (maximum + 1) / 2.\nOnce paralysis ends, accumulated damage falls by 10% each turn, rounded up. Other disabling effects can still prevent action.";
            if(buff.target==Dungeon.hero&&Dungeon.hero!=null){Paralysis.ParalysisResist resistance=Dungeon.hero.buff(Paralysis.ParalysisResist.class);result+="\nYour current counted damage: "+(resistance==null?0:resistance.accumulatedDamage())+" damage points.";}
            return result;
        }
        if(buff instanceof Drowsy)return "_Falling asleep_\nBecomes Magical Sleep when the timer ends, unless you are immune to sleep. Incoming damage can interrupt the hero's drowsiness even before health is lost. Restorative sleep ends immediately at full health or when your rules disable healing.";
        if(buff instanceof MagicalSleep)return "_Sleeping and recovering_\nNormally restores 1 HP per turn to sleeping allies; healing rules can change this amount. Allies wake at full health, and the hero wakes if restorative healing is disabled. Enemies do not receive this healing. Damage or other wake-up effects can end sleep early; any separate paralysis can still prevent action.";
        if(buff instanceof FireImbue){FireImbue fire=(FireImbue)buff;return "_Fire imbue_\nAttacks have a "+n(100f/FireImbue.IGNITION_ROLL_SIDES)+"% chance to ignite targets that can burn. Protects you from Burning and extinguishes existing Burning. Remaining duration: "+n(fire.remainingDuration())+" turns. This does not protect against every fire-related effect.";}
        if(buff instanceof FrostImbue)return "_Frost imbue_\nAttacks add "+n(FrostImbue.CHILL_DURATION)+" turns of Chill, adjusted by the target's resistance. Repeated hits extend the chilling. Chill can slow actions to half speed; Slow takes priority instead of stacking with it. Protects you from Chill and Frost and removes them when applied. Other cold-related damage can still hurt you.";
        if(buff instanceof Adrenaline)return "_Faster movement_\nDoubles movement speed, so the same step takes half as long. Other movement effects still apply. Monsters' ordinary attacks also take two thirds of their usual time; the hero does not gain this attack-speed bonus. Damage is unchanged.";
        if(buff instanceof Cripple)return "_Movement penalty_\nHalves movement speed, so the same step takes twice as long. Other movement effects still apply. It does not slow attacks or reduce damage.";
        if(buff instanceof Stamina)return "_Movement bonus_\nMovement is 50% faster, so the same step takes two thirds of its usual time. Attacks and damage are unchanged. Other movement effects still apply.";
        if(buff instanceof Fury)return "_Fury_\nIncreases physical attack damage by 50% before defenses and other attack effects. Ends on its next update if health is above "+n(100*Fury.LEVEL)+"% of maximum. It stays active at exactly that threshold.";
        if(buff instanceof Healing){Healing healing=(Healing)buff;return "_Healing over time_\nNext base heal: "+healing.nextRequestedHealing()+" HP. Healing reserve: "+healing.remainingHealingPool()+" HP. Healing rules and missing health determine how much is restored, but the reserve still pays the base amount.\n\n_Per-turn calculation_\n"+n(100*healing.healingRate())+"% of the remaining pool, rounded, plus "+healing.flatHealing()+" HP. At least 1 HP is used while healing remains, without exceeding the reserve. "+(healing.healingPerTickLimit()==Integer.MAX_VALUE?"No Blood Vial limit applies.":"Blood Vial limits this to "+healing.healingPerTickLimit()+" HP per turn.")+" A new application keeps the larger reserve and stronger rate and flat bonus; the reserves do not add together.";}
        if(buff instanceof Burning){Burning burning=(Burning)buff;return "_Burning_\nBase damage per turn: 1–"+burning.apdRandomMaximum()+" damage points, with middle values more likely. Remaining duration: "+n(burning.apdRemaining())+" turns. Protection and other damage rules can change health lost.\nWater extinguishes fire when grounded, but a newly ignited target can take one turn of damage first. Some potion splashes also extinguish it. Burning can ignite terrain and exposed items; containers protect their contents.";}
        if(buff instanceof Corrosion){Corrosion corrosion=(Corrosion)buff;return "_Growing corrosion_\nNext base damage: "+corrosion.apdNextRaw()+" damage points. Remaining duration: "+n(corrosion.apdRemaining())+" turns. Base damage grows each turn: first by 1, then by 0.5 once it reaches "+(Dungeon.scalingDepth()/2+2)+". Half points are rounded down.\nProtection and other damage rules can change health lost. Reapplying keeps the stronger damage and longer duration; the two amounts do not add together.";}
        if(buff instanceof Ooze){Ooze ooze=(Ooze)buff;return "_Caustic ooze_\nNext base damage: "+ooze.apdNextRaw()+" damage points. Remaining duration: "+n(ooze.apdRemaining())+" turns. "+(Dungeon.scalingDepth()<5?"On this floor it damages every other turn.":"On this floor it damages every turn.")+" Protection and other damage rules can change health lost.\nWater washes it off when grounded. A freshly applied coating can still hurt once before washing off; flying prevents water from cleaning it away.";}
        if(buff instanceof AdrenalineSurge){AdrenalineSurge surge=(AdrenalineSurge)buff;return "_Temporary strength_\nAdded strength: "+surge.boost()+". Loses 1 strength in "+n(Math.max(0,surge.visualcooldown()))+" turns, then another every "+n(surge.weakeningInterval())+" turns until the bonus is gone.";}
        if(buff instanceof com.shatteredpixel.shatteredpixeldungeon.actors.hero.abilities.warrior.Endure.EndureTracker){
            com.shatteredpixel.shatteredpixeldungeon.actors.hero.abilities.warrior.Endure.EndureTracker endure=(com.shatteredpixel.shatteredpixeldungeon.actors.hero.abilities.warrior.Endure.EndureTracker)buff;
            if(!endure.enduring)return "_Retaliation ready_\nExtra damage per hit: _"+endure.damageBonus+"_.\nHits remaining: _"+endure.hitsLeft+"_.\n\nThis bonus was fixed when you finished enduring. Enemy defenses still apply; misses do not spend a hit. The bonus fades if unused.";
            String state="Stored retaliation: "+endure.damageBonus+" damage points. Your talents determine the final bonus per hit.";
            return "_Endure state_\n"+state+(buff.target instanceof com.shatteredpixel.shatteredpixeldungeon.actors.hero.Hero?AbilityExplanation.effects(new com.shatteredpixel.shatteredpixeldungeon.actors.hero.abilities.warrior.Endure(),(com.shatteredpixel.shatteredpixeldungeon.actors.hero.Hero)buff.target):"");
        }
        if(buff instanceof com.shatteredpixel.shatteredpixeldungeon.actors.hero.abilities.huntress.NaturesPower.naturesPowerTracker){
            com.shatteredpixel.shatteredpixeldungeon.actors.hero.abilities.huntress.NaturesPower.naturesPowerTracker power=(com.shatteredpixel.shatteredpixeldungeon.actors.hero.abilities.huntress.NaturesPower.naturesPowerTracker)buff;
            return "_Nature's Power extensions_\nRemaining qualifying extension opportunities: "+power.extensionsLeft+". Only a positive extension spends an opportunity."+(buff.target instanceof com.shatteredpixel.shatteredpixeldungeon.actors.hero.Hero?AbilityExplanation.effects(new com.shatteredpixel.shatteredpixeldungeon.actors.hero.abilities.huntress.NaturesPower(),(com.shatteredpixel.shatteredpixeldungeon.actors.hero.Hero)buff.target):"");
        }
        if(buff instanceof com.shatteredpixel.shatteredpixeldungeon.actors.hero.abilities.cleric.AscendedForm.AscendBuff){
            com.shatteredpixel.shatteredpixeldungeon.actors.hero.abilities.cleric.AscendedForm.AscendBuff form=(com.shatteredpixel.shatteredpixeldungeon.actors.hero.abilities.cleric.AscendedForm.AscendBuff)buff;
            return "_Current ascended resources_\nForm shield: "+form.shielding()+" points. Remaining form updates: "+form.left+". Counted spell casts: "+form.spellCasts+". Flash uses counted: "+form.flashCasts+". These are separate shield, time and use resources; inspecting does not change them."+(buff.target instanceof com.shatteredpixel.shatteredpixeldungeon.actors.hero.Hero?AbilityExplanation.effects(new com.shatteredpixel.shatteredpixeldungeon.actors.hero.abilities.cleric.AscendedForm(),(com.shatteredpixel.shatteredpixeldungeon.actors.hero.Hero)buff.target):"");
        }
        if(buff instanceof com.shatteredpixel.shatteredpixeldungeon.actors.hero.abilities.cleric.PowerOfMany.PowerBuff)return "_Powered ally_\nAn existing ally keeps its own stats and equipment."+AbilityExplanation.effects(new com.shatteredpixel.shatteredpixeldungeon.actors.hero.abilities.cleric.PowerOfMany(),Dungeon.hero);
        if(buff instanceof com.shatteredpixel.shatteredpixeldungeon.actors.hero.abilities.duelist.Challenge.DuelParticipant){
            com.shatteredpixel.shatteredpixeldungeon.actors.hero.abilities.duelist.Challenge.DuelParticipant duel=(com.shatteredpixel.shatteredpixeldungeon.actors.hero.abilities.duelist.Challenge.DuelParticipant)buff;
            String current="_Current duel counter_\nRemaining scheduled duel updates: "+duel.remainingDuelUpdates()+".";
            if(buff.target==Dungeon.hero)current+=" Your tracked HP/shield damage suffered: "+duel.trackedDamage()+" points. This is the potential healing formula's input, not guaranteed health restored.";
            return current+AbilityExplanation.effects(new com.shatteredpixel.shatteredpixeldungeon.actors.hero.abilities.duelist.Challenge(),Dungeon.hero);
        }
        if(buff instanceof AscensionChallenge){
            AscensionChallenge ascent=(AscensionChallenge)buff;
            return "_Amulet's curse_\nCurrent pressure: "+n(ascent.pressure())+". Entering a new non-boss ascent floor adds 2. Defeating an enemy strengthened by the ascent removes 1, or 0.5 for a ghoul or ripper demon, down to zero. Other enemies do not reduce it.\n\n_Pressure thresholds_\n2+: enemies more than 8 tiles away are drawn toward you.\n4+: enemies move twice as fast unless hunting or fleeing.\n6+: your walking speed is halved and cannot exceed normal speed. Attacks are unchanged.\n8+: on non-boss floors, adds (pressure − 4) / 4 damage per turn, before protection. Fractions carry over until a whole point can be dealt. Boss floors and pressure below 8 clear this damage buildup.\nCurrent buildup: "+n(ascent.damageProgress())+" damage points. Next turn: "+ascent.nextPressureInput()+" damage points before protection. Enemy stat bonuses depend on their type, separately from these thresholds.";
        }
        if(buff instanceof Hunger){
            Hunger hunger=(Hunger)buff;
            return "_Hunger_\nCurrent hunger: "+n(hunger.hungerPoints())+" points; hungry at "+n(Hunger.HUNGRY)+" and starving at "+n(Hunger.STARVING)+" points. Food lowers this number, normally stopping at zero. Hunger normally rises by 1 point per turn. Shadows slows it to two thirds; Salt Cube and your hunger setting can also change the rate. The hunger-rate setting does not change food's nutrition.\n\n_Starvation damage_\nReaching starvation causes 1 base damage immediately. Afterward, damage builds at 0.1% of maximum HP per turn and is dealt in whole points once the reserve exceeds 1. Current reserve: "+n(hunger.starvationDamageProgress())+" damage points. Next unpaused starving turn: "+hunger.nextStarvationInput()+" base damage before protection. Slower hunger growth does not stop damage while already starving.\n\nHunger and starvation damage pause on locked floors, during the introduction, while Well Fed, or while Challenge Arena is active.";
        }
        if(buff instanceof Blindness)return "_Limited vision_\nLimits ordinary vision to nearby tiles. You can still attack visible adjacent targets, and other senses can help locate distant enemies. Overlapping sensing ranges use the maximum, not adding them together. Blindness prevents normal scroll and tome reading. It does not directly reduce accuracy or discover hidden doors.";
        if(buff instanceof Amok)return "_Angry target selection_\nWhen choosing a new target, normally prefers visible enemy monsters, then visible allies, then the visible hero. It does not choose randomly between friends and foes or become a permanent ally. Distance, reachability, its current target, fear, charm and special enemy behavior can change whom it attacks.";
        if(buff instanceof Charm)return "_Charmed_\nCannot directly attack the charmer. Other targets and indirect effects follow their usual rules. Each incoming-damage recovery check shortens the effect by 5 turns, even before shields or defenses reduce the hit. Some sources ignore allied attacks or protect the next check; an ignored allied attack does not use up that protection.";
        if(buff instanceof Terror)return "_Fleeing in terror_\nFlees from the source of its fear. Each incoming-damage recovery check shortens the effect by 5 turns, regardless of damage amount; some sources protect one check from this reduction. The check happens before final health loss, so even shielded hits can shorten fear.";
        if(buff instanceof Dread)return "_Fleeing the floor_\nCan leave when out of your sight and at least "+Dread.FLEE_DISTANCE+" tiles away. Leaves no ordinary loot and awards half experience, rounded down. Remaining fear updates: "+((Dread)buff).remainingFearUpdates()+"; normally 1 is used each turn, and each incoming-damage recovery check removes 5. Replaces ordinary Terror.";
        if(buff instanceof Vertigo)return "_Unpredictable walking_\nEach ordinary step chooses one of the eight neighboring directions at random. If it is blocked or occupied, the character stays put; it does not keep rerolling for an open tile. Large characters still need enough space. This does not redirect teleportation. Ally swapping is blocked while either character has Vertigo.";
        if(buff instanceof Light)return "_More light_\nRaises base sight to at least "+Light.DISTANCE+" tiles, keeping a larger ordinary range. Farsight and sight-altering trinkets still apply; walls and blindness still limit vision. When Light ends, base sight returns to the floor's normal range.";
        if(buff instanceof LifeLink)return "_Sharing damage_\nSplits eligible damage equally between the creature hit and its active Life Links. Each share rounds up, then that creature's own defenses apply. With one link, each receives half before rounding.\n\n_Share calculation_\nceil(incoming damage / (active link count + 1)). Because each rounds up, combined raw shares can exceed the original damage. Hunger and damage already shared through Life Link are not split again.";
        if(buff instanceof SoulMark){
            int siphon=Dungeon.hero==null?0:Dungeon.hero.pointsInTalent(com.shatteredpixel.shatteredpixeldungeon.actors.hero.Talent.SOUL_SIPHON),eater=Dungeon.hero==null?0:Dungeon.hero.pointsInTalent(com.shatteredpixel.shatteredpixeldungeon.actors.hero.Talent.SOUL_EATER);
            return "_Soul Mark healing_\nPhysical hits against a marked creature restore _40%_ of the counted damage as HP, rounded up before healing modifiers. Count attack damage before armor, up to the creature's remaining HP plus shielding. Later protection can reduce the creature's health lost without reducing this healing.\n\n_Your talents_\nWith Soul Siphon, other creatures' attacks count at _"+n(100f*.4f*siphon/3f)+"%_ of their damage, rounded to the nearest point first. Soul Eater restores _"+n(eater/3f)+" nutrition_ per counted damage point. A marked enemy's death has a _"+n(Math.min(100,10*eater))+"% chance_ to activate food-related talents without consuming food. Allies and enemies too weak to drop loot do not grant this death bonus.";
        }
        if(buff instanceof Bless || buff instanceof Hex || buff instanceof Daze){
            float factor=buff instanceof Bless?Bless.ROLL_FACTOR:buff instanceof Hex?Hex.ROLL_FACTOR:Daze.ROLL_FACTOR;
            return "_Accuracy and evasion_\n"+(factor>1?"Strengthens":"Weakens")+" attack and dodge rolls by "+n(100*Math.abs(factor-1))+"%. This is not a fixed change in hit or dodge chance: the attack hits when its roll matches or exceeds the defender’s roll, so the opponent’s abilities also matter.\n\n_Combined effects_\nBless ×"+n(Bless.ROLL_FACTOR)+", Hex ×"+n(Hex.ROLL_FACTOR)+" and Daze ×"+n(Daze.ROLL_FACTOR)+" multiply together. Bless and Hex together give ×"+n(Bless.ROLL_FACTOR*Hex.ROLL_FACTOR)+" before other bonuses. Guaranteed dodges override guaranteed hits; eligible surprise attacks follow their own rules.";
        }
        if(buff instanceof Frost)return "_Frozen_\nPrevents normal actions. An incoming hit can break the ice before shields absorb its damage. Extinguishes Burning when applied and removes Chill if freezing succeeds. Thawing over a water tile adds "+n(Chill.DURATION/2f)+" turns of Chill before resistance.\n\n_Freezing belongings_\nOutside the vault, the hero can lose one exposed, non-unique backpack potion or mystery meat: the potion shatters, or the meat becomes frozen carpaccio. Containers protect their contents. A thief's stolen potion or meat can also freeze.";
        if(buff instanceof Levitation)return "_Floating above the ground_\nRemoves Roots and avoids normal ground traps and pits. Water cannot wash off Ooze or extinguish Burning while flying. Webs and sacrificial fire can still affect you; walls still block movement, and doors can open as you pass. When levitation ends, ground hazards on your current tile can affect you, including pits.";
        if(buff instanceof Roots)return "_Rooted movement_\nPrevents walking and movement abilities that check for Roots. You can still attack or wait. Teleportation follows its own rules. Flying prevents Roots, and Levitation removes them.";
        if(buff instanceof MagicImmune)return "_Anti-magic protection_\nBlocks specific magical attacks and statuses, including Hex, Weakness and Magical Sleep. Removes matching statuses when applied. Physical attacks and other unblocked effects can still hurt you.\n\n_Suppressed equipment_\nRing bonuses, weapon enchantments and armor glyphs stop working. Wand use and charging are normally blocked. Armor abilities still work, including Wild Magic's wand casts. Equipment is not permanently downgraded or uncursed.";
        if(buff instanceof ToxicImbue){int releases=Math.max(0,(int)Math.ceil(((ToxicImbue)buff).emissionUpdatesLeft()));return "_Spreading toxic gas_\nGas releases left: "+releases+". Releases gas each turn, even while waiting; movement is not required. Protects against Poison and Toxic Gas until "+n(ToxicImbue.PROTECTION_AFTER_EMISSION)+" turns after emission ends, and removes existing Poison when applied. Gas can harm allies. The emission icon can disappear while protection remains.\n\n_Gas amount_\nEach release adds "+(9*ToxicImbue.GAS_PER_CELL)+" gas-volume units: "+ToxicImbue.GAS_PER_CELL+" per open neighboring tile and the remainder on your tile. These are cloud quantities, not direct damage points; the cloud spreads and harms vulnerable creatures under the gas's normal rules.";}
        if(buff instanceof LockedFloor)return "_Recovery on a locked floor_\nRecovery grace: "+n(((LockedFloor)buff).remainingGraceTime())+" turns. Passive recovery requires at least 1; other recovery conditions still apply. Each normal locked-floor update uses 1 while enough remains. Starts at 50, or 20 with Badder Bosses. Encounter progress can restore it up to 50; setbacks can reduce it below zero.\nHunger and starvation damage stay paused even when recovery grace runs out. Unlocking ends this effect.";
        if(buff instanceof BlobImmunity)return "_Protection from environmental hazards_\nProtects against harmful gases, fire and freezing fields, electricity, webs and certain special flames. This does not block ordinary attacks or every area effect. Burning and Poison are separate effects and can still hurt you.";
        if(buff instanceof Foresight)return "_Foresight-assisted searching_\nSearches and maps within "+Foresight.DISTANCE+" tiles, including through walls. Reveals hidden doors and traps in that area, even traps ordinary searching cannot find. The area follows the search radius rather than mapping the whole floor. Automatic checks cost no extra Search action; choosing Search still takes its normal time and hunger. Revealed walls still block projectiles.";
        if(buff instanceof EnhancedRings)return "_Temporary ring upgrade_\nYour rings gain the benefits of one extra upgrade while this lasts. Each ring uses its own upgrade rules. Might's strength bonus and Sharpshooting's missile durability are unchanged because they use actual upgrades. This does not permanently upgrade or identify rings, and anti-magic can still suppress their effects.";
        if(buff instanceof PrismaticGuard){PrismaticGuard guard=(PrismaticGuard)buff;return "_Waiting prismatic image_\nStored health: "+n(guard.storedHealth())+" / "+guard.maxHP()+" HP. Maximum = 10 + floor(2.5 × hero level). While below this maximum, recovers 0.1 HP per turn when passive recovery is allowed. Its icon rounds health down.\n\n_Appearing beside you_\nNeeds a directly visible enemy within 4 tiles and a free, walkable neighboring tile. Sleeping, wandering, passive enemies and enemies invulnerable to the image do not trigger it; Mind Vision alone is insufficient. Appears with its stored HP rounded down and carries over remaining Power of Many time. This is the image's health, not shielding for you.";}
        if(buff instanceof GreaterHaste)return "_Instant movement_\nRemaining haste units: "+((GreaterHaste)buff).remainingHasteUnits()+". Walking costs no time, but each step uses 1 unit. Each scheduled update (normally once per turn) also uses 1, so taking other actions can reduce the steps left. Attacks retain their normal time cost. Obstacles, traps and movement restrictions still apply.";
        if(buff instanceof WellFed)return "_Nutrition and healing_\nPauses ordinary hunger and normally heals 1 HP every "+WellFed.HEAL_INTERVAL+" updates while hurt, adjusted by healing rules. Salt Cube stretches the intervals and duration without reducing healing opportunities.\n\n_Timing_\nRemaining updates: "+((WellFed)buff).remainingNutritionUpdates()+". Each update lowers this count by 1; healing occurs at each multiple of "+WellFed.HEAL_INTERVAL+". Updates are normally one turn apart; Salt Cube lengthens this interval. The effect ends when the count falls below zero. Resetting supplies "+ObfuscationExplanation.number(Hunger.STARVING)+" updates, or one third under On Diet. Effects that consume hunger can shorten it.";
        if(buff instanceof Preparation)return PreparedShotExplanation.preparation((Preparation)buff);
        if(buff instanceof SnipersMark)return PreparedShotExplanation.sniper((SnipersMark)buff);
        if(buff instanceof PhysicalEmpower){PhysicalEmpower empower=(PhysicalEmpower)buff;return "_Added physical damage_\nAdds "+empower.dmgBoost+" damage to each of the next "+empower.left+" hero physical damage rolls, before later effects and defenses. Multiple rolls in one action can use several charges. A new bonus replaces this one only when its total potential bonus damage (damage per roll × rolls left) is greater. The two bonuses do not add together.";}
        if(buff instanceof WandEmpower){WandEmpower empower=(WandEmpower)buff;return "_Added wand damage_\nAdds "+empower.dmgBoost+" damage to each of the next "+empower.left+" direct wand damage rolls, before defenses. A zap with several damage rolls can use several charges; indirect damage may not benefit. Reapplying replaces the damage bonus and keeps the larger number of rolls left.";}
        if(buff instanceof Degrade){
            StringBuilder result=new StringBuilder("_Weakened upgrades_\nUpgrade levels above +3 give smaller bonuses while Degraded. Your real upgrades and strength requirements stay unchanged. Wands keep their normal charge capacity, thrown weapons keep their durability, and artifacts are unaffected.\n\n_Upgrade rule_\nFor levels above +3, use √[2 × (level − 1)] + 1, rounded to the nearest whole level. Lower levels stay unchanged.");
            if(buff.target==Dungeon.hero&&buff.target instanceof Hero){
                Hero hero=(Hero)buff.target;boolean heading=false;
                for(Item item:new Item[]{hero.belongings.weapon(),hero.belongings.armor(),hero.belongings.ring(),hero.belongings.misc()}){
                    if(item!=null&&!(item instanceof com.shatteredpixel.shatteredpixeldungeon.items.artifacts.Artifact)&&item.levelKnown){
                        if(!heading){result.append("\n\n_Known equipment, before other bonuses_");heading=true;}
                        int level=item.level(),reduced=Degrade.reduceLevel(level);
                        result.append("\n").append(item.name()).append(": _").append(level>=0?"+":"").append(level).append(" → ").append(reduced>=0?"+":"").append(reduced).append("_");
                    }
                }
            }
            return result.toString();
        }
        if(buff instanceof Doom)return "_Doom_\nIncreases incoming damage by _67%_ before other protection and rounding. Immunity and defenses still apply. It does not expire on its own.";
        if(buff instanceof Corruption)return "_Corruption_\nTurns a creature against its former allies. It gradually takes damage based on _1% of maximum HP per turn_, before protection. Fractions carry over until a whole damage point can be dealt, so small health pools lose HP less often. Corruption does not expire on its own.";
        if(buff instanceof Berserk){Berserk rage=(Berserk)buff;return "_Rage and damage_\nCurrent rage: "+n(100*rage.rageFraction())+"%. Its damage factor is min(1.5, 1 + rage / 2), where 100% rage means rage = 1; current factor: "+n(rage.damageFactor(1))+" times normal at this step. Rage above 100% does not raise that factor past 1.5. The berserk shield formula starts from 8 + 2 × effective armor level (zero armor contribution when no armor is available) and multiplies by 1 + 2 × (missing-HP fraction)³, then by rage when rage exceeds 1, with integer rounding. Active berserk shield loss is based on total current shielding, not a fixed amount: ceil(total shield × 0.025), modified by Hold Fast and fractional rounding. Shield/HP, armor, recovery and other effects still follow their own rules.";}
        if(buff instanceof ChampionEnemy){
            ChampionEnemy champion=(ChampionEnemy)buff;
            String result="_Champion bonuses_\nAttack damage: "+n(100*champion.meleeDamageFactor())+"% of normal. Accuracy and dodge rolls: "+n(100*champion.evasionAndAccuracyFactor())+"% of normal. Damage taken: "+n(100*champion.damageTakenFactor())+"% of normal, rounded up. These are changes to damage and rolls, not fixed hit or dodge chances. Other defenses and immunities still apply.";
            if(buff instanceof ChampionEnemy.Growing)result+="\nGrowth raises attack, accuracy and dodge rolls by 1 percentage point every four turns, without a cap. Damage taken falls as it grows: its percentage equals 10,000 divided by the attack-damage percentage above.";
            if(buff instanceof ChampionEnemy.Projecting)result+="\nExtra-reach attacks require a legal path of at most four tiles through non-solid terrain, without other creatures blocking the path. The extra reach does not mean an attack can pass through a wall.";
            if(buff instanceof ChampionEnemy.Giant)result+="\nExtra-reach attacks require a legal path of at most two tiles through non-solid terrain, without other creatures blocking the path. Large-creature movement restrictions still apply.";
            if(buff instanceof ChampionEnemy.AntiMagic)result+="\nImmune to many spells and harmful effects, including Hex, Weakness, Charm and Magical Sleep. Some magical attacks can still hurt it.";
            return result;
        }
        return "";
    }
}
